def dict_depth(d):
    if not isinstance(d, (dict, list, tuple)):
        return 0
    if isinstance(d, dict):
        if not d:
            return 1
        return 1 + max(dict_depth(v) for v in d.values())
    else:  # list or tuple
        if not d:
            return 1
        return 1 + max(dict_depth(item) for item in d)

def sum_column(data, col_index):
    total = None
    for row in data:
        if col_index < len(row):
            value = row[col_index]
            if total is None:
                total = value
            else:
                total += value
    return total
